std::vector<std::vector<cg3::Point2d>> result;
if (points.empty())
    return result;

internal::DT dt;
for (const auto& p : points) {
    dt.insert(internal::Point_2(p.x(), p.y()));
}

internal::VD vd(dt);

for (auto fit = vd.faces_begin(); fit != vd.faces_end(); ++fit) {
    if (fit->is_unbounded())
        continue;

    std::vector<cg3::Point2d> cell;
    internal::Ccb_halfedge_circulator ec = fit->ccb_halfedges_begin();
    if (ec == internal::Ccb_halfedge_circulator())
        continue;
    internal::Ccb_halfedge_circulator done = ec;
    do {
        internal::Vertex_handle vh = ec->source();
        if (!vd.is_infinite(vh)) {
            const internal::Point_2& pt = vh->point();
            cell.emplace_back(pt.x(), pt.y());
        }
        ++ec;
    } while (ec != done);

    result.push_back(std::move(cell));
}
return result;

